17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.IdentityKeyResolver;
31	import org.springframework.samples.petclinic.mapper.MembershipLevelResolver;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.Region;
35	import org.springframework.samples.petclinic.mapper.VisitMapper;
36	import org.springframework.samples.petclinic.model.Owner;
37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
40	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
41	import org.springframework.samples.petclinic.rest.advice.FutureRegistrationDateException;
42	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
43	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
44	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
45	import org.springframework.samples.petclinic.rest.api.OwnersApi;
46	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
47	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.PetDto;
49	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitDto;
51	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
52	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
53	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
54	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
55	import org.springframework.samples.petclinic.service.ClinicService;
56	import org.springframework.security.access.prepost.PreAuthorize;
57	import org.springframework.web.bind.annotation.CrossOrigin;
58	import org.springframework.web.bind.annotation.RequestMapping;
59	import org.springframework.web.bind.annotation.RestController;
60	import org.springframework.web.util.UriComponentsBuilder;
61	
62	import jakarta.transaction.Transactional;
63	
64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
74	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
75	
76	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
77	    private static final int MAX_OWNERS_PER_CITY = 50;
78	
79	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
80	    private static final int MAX_OWNERS_PER_DAY = 100;
81	
82	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
83	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
84	
85	    private final ClinicService clinicService;
86	
87	    private final OwnerMapper ownerMapper;
88	
89	    private final PetMapper petMapper;
90	
91	    private final VisitMapper visitMapper;
92	
93	    private final TelephoneNormalizer telephoneNormalizer;
94	
95	    private final AddressNormalizer addressNormalizer;
96	
97	    private final EmailNormalizer emailNormalizer;
98	
99	    private final IdentityKeyResolver identityKeyResolver;
100	
101	    public OwnerRestControllerV1(ClinicService clinicService,
102	                                 OwnerMapper ownerMapper,
103	                                 PetMapper petMapper,
104	                                 VisitMapper visitMapper,
105	                                 TelephoneNormalizer telephoneNormalizer,
106	                                 AddressNormalizer addressNormalizer,
107	                                 EmailNormalizer emailNormalizer,
108	                                 IdentityKeyResolver identityKeyResolver) {
109	        this.clinicService = clinicService;
110	        this.ownerMapper = ownerMapper;
111	        this.petMapper = petMapper;
112	        this.visitMapper = visitMapper;
113	        this.telephoneNormalizer = telephoneNormalizer;
114	        this.addressNormalizer = addressNormalizer;
115	        this.emailNormalizer = emailNormalizer;
116	        this.identityKeyResolver = identityKeyResolver;
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
122	        Collection<Owner> owners;
123	        if (lastName != null) {
124	            owners = this.clinicService.findOwnerByLastName(lastName);
125	        } else {
126	            owners = this.clinicService.findAllOwners();
127	        }
128	        if (owners.isEmpty()) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        owners.forEach(this::populateHouseholdMemberCount);
132	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
133	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        populateHouseholdMemberCount(owner);
144	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
145	    }
146	
147	    /**
148	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
149	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
150	     * by the mapper alone.
151	     *
152	     * @param owner the owner to map
153	     * @return the owner DTO carrying its identity key
154	     */
155	    private OwnerDto toOwnerDto(Owner owner) {
156	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
157	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
158	        return ownerDto;
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Transactional
163	    @Override
164	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
165	        normalizeAndValidate(ownerFieldsDto);
166	        HttpHeaders headers = new HttpHeaders();
167	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
168	        populateDerivedFields(owner, ownerFieldsDto);
169	        requireUniqueIdentity(owner);
170	        this.clinicService.saveOwner(owner);
171	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
172	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
173	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount()));
174	        populateHouseholdMemberCount(owner);
175	        OwnerDto ownerDto = toOwnerDto(owner);
176	        headers.setLocation(UriComponentsBuilder.newInstance()
177	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
178	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
179	    }
180	
181	    /**
182	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
183	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
184	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
185	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
186	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
187	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), backfilling any existing household members
188	     * that lack it, so it is in place before {@link #requireUniqueIdentity} derives the identity key. The owner is
189	     * mutated in place; the caller applies the duplicate guard and saves it.
190	     *
191	     * @param owner          the newly mapped owner about to be saved
192	     * @param ownerFieldsDto the incoming owner payload
193	     */
194	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
195	        owner.setCustomerCode(identityKeyResolver.deriveCustomerCode(owner));
196	        owner.setNamesakeCount(countNamesakes(owner));
197	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
198	        assignHouseholdId(owner, ownerFieldsDto);
199	    }
200	
201	    /**
202	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
203	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
204	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
205	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
206	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
207	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
208	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
209	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
210	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
211	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
212	     * assigned (see {@link #requireUniqueIdentity}).
213	     *
214	     * @param ownerFieldsDto the incoming owner payload, mutated in place
215	     * @throws MissingOwnerFieldsException if any required field is missing or blank
216	     */
217	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
218	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
219	        validateRequiredFields(ownerFieldsDto);
220	        validatePostcode(ownerFieldsDto);
221	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
222	        ownerFieldsDto.setTelephone(telephone);
223	        requireCityHasCapacity(ownerFieldsDto.getCity());
224	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
225	        ownerFieldsDto.setRegistrationDate(registrationDate);
226	        requireDailyLimitNotReached(registrationDate);
227	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
228	        ownerFieldsDto.setEmail(email);
229	    }
230	
231	    /**
232	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
233	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
234	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day. A supplied date
235	     * later than the current server date is rejected.
236	     *
237	     * @param ownerFieldsDto the incoming owner payload
238	     * @return the effective registration date rolled forward onto a business day
239	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
240	     */
241	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
242	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
243	        if (effective == null) {
244	            effective = LocalDate.now();
245	        }
246	        else if (effective.isAfter(LocalDate.now())) {
247	            throw new FutureRegistrationDateException(
248	                "the registration date must not be later than the current server date");
249	        }
250	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
251	            effective = effective.plusDays(1);
252	        }
253	        return effective;
254	    }
255	
256	    /**
257	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
258	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
259	     * further owner may be created for that day.
260	     *
261	     * @param registrationDate the adjusted business-day registration date of the owner being created
262	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
263	     */
264	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
265	        long createdThatDay = this.clinicService.findAllOwners().stream()
266	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
267	            .count();
268	        if (createdThatDay >= MAX_OWNERS_PER_DAY) {
269	            throw new DailyOwnerLimitExceededException(
270	                "the maximum number of owners for today has already been reached");
271	        }
272	    }
273	
274	    /**
275	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
276	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
277	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
278	     * reflects only owners that predate it.
279	     *
280	     * @param registrationDate the adjusted business-day registration date of the owner being created
281	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
282	     */
283	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
284	        long createdThatDay = this.clinicService.findAllOwners().stream()
285	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
286	            .count();
287	        return createdThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
288	    }
289	
290	    /**
291	     * Counts how many existing owners already share the given owner's first and last name, compared
292	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
293	     * create; it is zero when the owner's name is unique.
294	     *
295	     * @param owner the newly mapped owner about to be saved
296	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
297	     */
298	    private int countNamesakes(Owner owner) {
299	        String firstName = owner.getFirstName();
300	        String lastName = owner.getLastName();
301	        return (int) this.clinicService.findAllOwners().stream()
302	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
303	                && lastName.equalsIgnoreCase(existing.getLastName()))
304	            .count();
305	    }
306	
307	    /**
308	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
309	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
310	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
311	     *
312	     * @param ownerFieldsDto the owner payload to validate
313	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
314	     */
315	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
316	        List<String> missingFields = new ArrayList<>();
317	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
318	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
319	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
320	        requireText(missingFields, "city", ownerFieldsDto.getCity());
321	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
322	        if (!missingFields.isEmpty()) {
323	            throw new MissingOwnerFieldsException(missingFields);
324	        }
325	    }
326	
327	    private void requireText(List<String> missingFields, String fieldName, String value) {
328	        if (value == null || value.isBlank()) {
329	            missingFields.add(fieldName);
330	        }
331	    }
332	
333	    /**
334	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
335	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
336	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
337	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
338	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
339	     *
340	     * @param ownerFieldsDto the incoming owner payload
341	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
342	     */
343	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
344	        String postcode = ownerFieldsDto.getPostcode();
345	        if (postcode == null) {
346	            return;
347	        }
348	        Region region = Region.forCity(ownerFieldsDto.getCity());
349	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
350	            throw new InvalidPostcodeException(
351	                "postcode " + postcode + " is not valid for the city's region " + region.name());
352	        }
353	    }
354	
355	    /**
356	     * Rejects creating an owner whose whole derived {@code identityKey} (see
357	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner. This is the single, consolidated
358	     * duplicate check: the former separate telephone, email and household rules are all expressed through this one key,
359	     * so an owner is a duplicate only when its normalized telephone, email and {@code householdId} all match another
360	     * owner's. It runs after the household id has been assigned, so the key reflects the household the owner belongs to.
361	     *
362	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
363	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
364	     */
365	    private void requireUniqueIdentity(Owner owner) {
366	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
367	        boolean inUse = this.clinicService.findAllOwners().stream()
368	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
369	        if (inUse) {
370	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
371	        }
372	    }
373	
374	    /**
375	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
376	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
377	     *
378	     * @param city the city of the owner being created
379	     * @throws OwnerCityFullException if the city already contains 50 or more owners
380	     */
381	    private void requireCityHasCapacity(String city) {
382	        long cityOwners = this.clinicService.findAllOwners().stream()
383	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
384	            .count();
385	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
386	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
387	        }
388	    }
389	
390	    /**
391	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
392	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
393	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
394	     * incidental formatting differences and abbreviation variants do not affect membership.
395	     *
396	     * @param ownerFieldsDto the incoming owner payload
397	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
398	     *         them; empty when none match
399	     */
400	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
401	        String lastName = identityKeyResolver.collapseWhitespace(ownerFieldsDto.getLastName());
402	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
403	        return this.clinicService.findAllOwners().stream()
404	            .filter(existing -> identityKeyResolver.collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
405	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
406	            .toList();
407	    }
408	
409	    /**
410	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
411	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
412	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
413	     * identifier is derived deterministically from the household's last name and address (see
414	     * {@link IdentityKeyResolver#deriveHouseholdId}), so every member of the same household resolves to the same stable
415	     * value regardless of creation order. Existing members that predate the feature and still lack the identifier are
416	     * backfilled (see {@link #backfillHouseholdMembers}) so the whole household shares it.
417	     *
418	     * @param owner          the newly mapped owner about to be saved
419	     * @param ownerFieldsDto the incoming owner payload
420	     */
421	    private void assignHouseholdId(Owner owner, OwnerFieldsDto ownerFieldsDto) {
422	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
423	            return;
424	        }
425	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
426	        if (members.isEmpty()) {
427	            return;
428	        }
429	        String householdId =
430	            identityKeyResolver.deriveHouseholdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
431	        owner.setHouseholdId(householdId);
432	        backfillHouseholdMembers(householdId, members);
433	    }
434	
435	    /**
436	     * Stamps the shared {@code householdId} onto the existing members of a household that do not already carry it,
437	     * persisting each one that changes. Members that predate the feature (and so still lack the identifier) are brought
438	     * into line so the whole household shares the single value; members that already carry it are left untouched.
439	     *
440	     * @param householdId the shared household identifier
441	     * @param members     the existing owners in the household
442	     */
443	    private void backfillHouseholdMembers(String householdId, List<Owner> members) {
444	        for (Owner member : members) {
445	            if (!householdId.equals(member.getHouseholdId())) {
446	                member.setHouseholdId(householdId);
447	                this.clinicService.saveOwner(member);
448	            }
449	        }
450	    }
451	
452	    /**
453	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
454	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
455	     * household is counted as a household of one.
456	     *
457	     * @param owner the owner whose household size should be resolved
458	     */
459	    private void populateHouseholdMemberCount(Owner owner) {
460	        String householdId = owner.getHouseholdId();
461	        if (householdId == null) {
462	            owner.setHouseholdMemberCount(1);
463	            return;
464	        }
465	        long members = this.clinicService.findAllOwners().stream()
466	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
467	            .count();
468	        owner.setHouseholdMemberCount((int) members);
469	    }
470	
471	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
472	    @Override
473	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
474	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
475	        if (currentOwner == null) {
476	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
477	        }
478	        validatePostcode(ownerFieldsDto);
479	        currentOwner.setAddress(ownerFieldsDto.getAddress());
480	        currentOwner.setCity(ownerFieldsDto.getCity());
481	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
482	        currentOwner.setLastName(ownerFieldsDto.getLastName());
483	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
484	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
485	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
486	        this.clinicService.saveOwner(currentOwner);
487	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
488	    }
489	
490	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
491	    @Transactional
492	    @Override
493	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
494	        Owner owner = this.clinicService.findOwnerById(ownerId);
495	        if (owner == null) {
496	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
497	        }
498	        this.clinicService.deleteOwner(owner);
499	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
500	    }
501	
502	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
503	    @Override
504	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
505	        Owner owner = this.clinicService.findOwnerById(ownerId);
506	        if (owner == null) {
507	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
508	        }
509	        HttpHeaders headers = new HttpHeaders();
510	        Pet pet = petMapper.toPet(petFieldsDto);
511	        owner.setId(ownerId);
512	        pet.setOwner(owner);
513	        pet.getType().setName(null);
514	        this.clinicService.savePet(pet);
515	        PetDto petDto = petMapper.toPetDto(pet);
516	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
517	            .buildAndExpand(pet.getId()).toUri());
518	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
519	    }
520	
521	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
522	    @Override
523	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
524	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
525	        if (currentOwner != null) {
526	            Pet currentPet = this.clinicService.findPetById(petId);
527	            if (currentPet != null) {
528	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
529	                currentPet.setName(petFieldsDto.getName());
530	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
531	                this.clinicService.savePet(currentPet);
532	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
533	            }
534	        }
535	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
536	    }
537	
538	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
539	    @Override
540	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
541	        HttpHeaders headers = new HttpHeaders();
542	        Visit visit = visitMapper.toVisit(visitFieldsDto);
543	        Pet pet = new Pet();
544	        pet.setId(petId);
545	        visit.setPet(pet);
546	        this.clinicService.saveVisit(visit);
547	        VisitDto visitDto = visitMapper.toVisitDto(visit);
548	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
549	            .buildAndExpand(visit.getId()).toUri());
550	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
551	    }
552	
553	
554	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
555	    @Override
556	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
557	        Owner owner = this.clinicService.findOwnerById(ownerId);
558	        if (owner != null) {
559	            Pet pet = owner.getPet(petId);
560	            if (pet != null) {
